local HttpService = game:GetService("HttpService")

local Config = require(ReplicatedStorage.Modules.Shared.Config.LobbyConfig)
local PlayerStore = require(ServerScriptService.Data.PlayerStore)
local Remotes = require(ServerScriptService.Lobby.LobbyRemotes)
-- [RANKED] Edward's ranked window (notes/ranked_server.md): RankedCore maths, RankedServer records
local RankedCore = require(ReplicatedStorage.Modules.Shared.RankedCore)
local RankedServer = require(ServerScriptService.Shared.RankedServer)
-- [PARTY] parties queue together (ServerScriptService.Shared.PartyService)
local PartyService = require(ServerScriptService.Shared.PartyService)

local MatchmakingManager = {}
-- [PLAYQUEUE] (lead 2026-10-25) THIS COPY is the match places' one (fix/play_again_queue.lua installs it; the hub keeps its own):
-- in a match place FindMatch is not on the shared Request remote (only RoundManager's Play Again calls it, after the match's
-- rewards are written and only in the after-match window), arrival TeleportData never auto-queues, and the pad watch is off.
local IS_MATCH_PLACE = ReplicatedStorage:FindFirstChild("PlaceKind") ~= nil

local IS_STUDIO = RunService:IsStudio()
local PREFIX = IS_STUDIO and "Studio_" or "" -- testing in Studio never touches the live queues
local TICK = 1.5          -- seconds between passes
local ENTRY_TTL = 90      -- a queue entry dies this long after its last refresh
local REFRESH_EVERY = 25
local RESULT_TTL = 120
local LOCK_TTL = 6
local COUNTS_EVERY = 4

local queueMaps = {}
-- [MM] offline-safe init (Edward 2026-10-16): MemoryStore throws in an unpublished place; load anyway and report offline
local OFFLINE = false
local function memMap(name: string)
	local ok, map = pcall(function() return MemoryStoreService:GetHashMap(name) end)
	if ok then return map end
	OFFLINE = true
	return nil
end
local results = memMap(PREFIX .. "MM_Results")
local locks = memMap(PREFIX .. "MM_Locks")
local stats = memMap(PREFIX .. "MM_Stats")
MatchmakingManager.IsOffline = function() return OFFLINE end

local searching = {}    -- [Player] = { queue, key, since, refreshed, status }
local running = {}      -- [queueId] = true while a matchmaker pass is in progress here
local countsWritten = {} -- [queueId] = os.clock() of the last count we published

local function queueMap(id: string)
	local m = queueMaps[id]
	if not m then
		m = MemoryStoreService:GetSortedMap(PREFIX .. "MMQ_" .. id)
		queueMaps[id] = m
	end
	return m
end

local function canRanked(player: Player): boolean
	local data = PlayerStore.Get(player)
	return Config.CanPlayRanked(data and data.XP or 0, IS_STUDIO)
end
MatchmakingManager.CanRanked = canRanked

local function ratingOf(player: Player, mode: string): number
	-- [RANKED] the unified record's Elo (lazy migration of the old Rating)
	return RankedServer.EloOf(player, mode)
end

local function setState(player: Player, queue: string?, status: string?)
	-- [PARTY] the leader's search state shows on every member too
	local targets = (PartyService.IsLeader(player) and PartyService.Members(player)) or { player }
	for _, p in targets do
		p:SetAttribute("MM_Queue", queue)
		p:SetAttribute("MM_Status", status)
		if status then p:SetAttribute("MM_FailReason", nil) end -- [MMFAIL] a new search clears the last failure
		if not status then p:SetAttribute("MM_Since", nil) elseif p ~= player then p:SetAttribute("MM_Since", player:GetAttribute("MM_Since")) end
	end
end

local function stop(player: Player)
	searching[player] = nil
	setState(player, nil, nil)
end

-------------------------------------------------------------------------------
-- Joining and leaving
-------------------------------------------------------------------------------
-- Takes the player's entry out of the queue. Returns false if a match already claimed them.
local function leaveQueue(s): boolean
	local claimed = false
	pcall(function()
		queueMap(s.queue):UpdateAsync(s.key, function(old, sortKey)
			if type(old) ~= "table" then return nil end
			if old.c then
				claimed = true
				return nil
			end
			claimed = false
			old.x = true -- cancelled: matchmakers skip it until it's gone
			return old, sortKey
		end, 30)
	end)
	if claimed then return false end
	pcall(function() queueMap(s.queue):RemoveAsync(s.key) end)
	return true
end

local function findMatch(player, queueId) -- [PLAYQUEUE] (was Remotes.Handlers.FindMatch; registered below)
	local q = Config.QueueById(queueId)
	if not q then return { ok = false, msg = "Unknown queue" } end
	-- [PARTY] RIVALS' "Whoops!" cases first, with the Play menu's exact strings (fix/party_queue_msgs.lua)
	do
		local pty = PartyService.Of(player)
		if pty then
			if pty.leader ~= player then return { ok = false, msg = "Only the party leader can join a queue!" } end
			if #pty.members > q.TeamSize then return { ok = false, msg = "This party is too big for this queue!" } end
			for _, m in pty.members do
				if m:GetAttribute("InDuel") or m:GetAttribute("DuelMatch") then
					return { ok = false, msg = "A party member (@" .. m.Name .. ") is currently in a duel!" }
				end
			end
		end
	end
	-- [MM] offline-safe: no MemoryStore here (unpublished place)
	if OFFLINE then return { ok = false, offline = true, msg = "Online matchmaking is offline here" } end
	if searching[player] then return { ok = false, msg = "You're already searching" } end
	if player:GetAttribute("QueueMode") then
		return { ok = false, msg = "You're on a lobby pad. Step off it to search online." }
	end
	if q.Ranked and not canRanked(player) then
		return { ok = false, msg = `Ranked unlocks at level {Config.RankedLevel}` }
	end
	-- [PARTY] only the leader queues, for the whole party (it must fit one team, and everyone must be free)
	local party = PartyService.Of(player)
	local partyIds, partyR = nil, nil
	if party then
		if party.leader ~= player then return { ok = false, msg = "Only the party leader can queue" } end
		if #party.members > q.TeamSize then return { ok = false, msg = `Your party is too big for {string.upper(q.Mode)}` } end
		partyIds, partyR = {}, 0
		for _, m in party.members do
			if m ~= player and (m:GetAttribute("QueueMode") or m:GetAttribute("DuelMatch") or m:GetAttribute("InTraining")) then
				return { ok = false, msg = m.DisplayName .. " is busy" }
			end
			if q.Ranked and not canRanked(m) then return { ok = false, msg = m.DisplayName .. ` hasn't unlocked ranked (level {Config.RankedLevel})` } end
			table.insert(partyIds, m.UserId)
			partyR += ratingOf(m, q.Mode)
		end
		partyR = partyR / #party.members
	end
	local key = tostring(player.UserId)
	local now = workspace:GetServerTimeNow()
	local entry = { u = player.UserId, j = game.JobId, r = ratingOf(player, q.Mode), t = now }
	-- [RANKED] the tier rides in the queue entry (k) for RankedCore's window
	entry.k = RankedCore.TierOf(entry.r)
	-- [PARTY] a party entry: n players, p their ids (leader first), queued at the party's average rating / tier
	if partyIds then entry.n = #partyIds; entry.p = partyIds; entry.r = partyR; entry.k = RankedCore.TierOf(partyR) end
	local ok, err = pcall(function()
		queueMap(q.Id):SetAsync(key, entry, ENTRY_TTL, now)
	end)
	if not ok then
		warn("[Matchmaking] couldn't join " .. q.Id .. ": " .. tostring(err))
		return { ok = false, msg = "Matchmaking is busy. Try again in a moment." }
	end
	-- [RANKED] tier kept with the search (the refresh below re-creates an expired entry with it)
	searching[player] = { queue = q.Id, key = key, since = now, refreshed = os.clock(), status = "Searching", rating = entry.r, tier = entry.k, n = entry.n, p = entry.p } -- [PARTY] n, p
	player:SetAttribute("MM_Since", now)
	setState(player, q.Id, "Searching")
	return { ok = true }
end

MatchmakingManager.FindMatch = findMatch
if not IS_MATCH_PLACE then Remotes.Handlers.FindMatch = findMatch end -- [PLAYQUEUE]
MatchmakingManager.IsSearching = function(player: Player): boolean return searching[player] ~= nil end -- [PLAYQUEUE]

Remotes.Handlers.CancelMatch = function(player)
	local s = searching[player]
	if not s then
		-- [PLAYQUEUE] a party member sees the leader's search: say who can stop it
		local party = PartyService.Of(player)
		if party and party.leader ~= player and searching[party.leader] then return { ok = false, msg = "Only the party leader can cancel the search" } end
		return { ok = false, msg = "You're not searching" }
	end
	if s.status ~= "Searching" then return { ok = false, msg = "Match found! Too late to cancel." } end
	if not leaveQueue(s) then return { ok = false, msg = "Match found! Hold on..." } end
	stop(player)
	return { ok = true, msg = "Stopped searching" }
end

-------------------------------------------------------------------------------
-- The matchmaker (runs on whichever server holds a queue's lease)
-------------------------------------------------------------------------------
local function tryLock(queueId: string): boolean
	local got = false
	pcall(function()
		locks:UpdateAsync(queueId, function(old)
			local now = os.time()
			if type(old) == "table" and old.j ~= game.JobId and (old.u or 0) > now then
				got = false
				return nil
			end
			got = true
			return { j = game.JobId, u = now + LOCK_TTL }
		end, LOCK_TTL + 4)
	end)
	return got
end

local function ratingWindow(waited: number): number
	local w = Config.RatingWindow
	return math.min(w.Max, w.Start + w.PerSecond * math.max(0, waited))
end

-- The next group of `need` players to put in a match, or nil.
-- Casual: simply the longest waiting. Ranked: the longest waiting player plus the oldest others
-- whose rating is close enough (the allowed gap grows while the first player waits).
-- [RANKED] mode = the queue's mode (RankedCore.Window widens faster in 2v2 / 3v3)
local function pickGroup(pool, need: number, ranked: boolean, now: number, mode: string?)
	if #pool < need then return nil end
	if not ranked then
		return table.move(pool, 1, need, 1, {})
	end
	-- [RANKED] Edward's window (RankedCore.Window: 1v1 2 tiers at 0 s, 6 at 5 min, 18 at 60 min; 2v2 twice and 3v3 four times
	-- as fast) and the pair rule (every pair inside each other's window), oldest first; a party entry (v.n players)
	-- queues at its average tier (v.k). The old rating-gap pick below is no longer reached.
	do return RankedCore.PickGroup(pool, need, now, mode) end
	for i, anchor in pool do
		local window = ratingWindow(now - anchor.v.t)
		local group = { anchor }
		for j, e in pool do
			if j ~= i and math.abs((e.v.r or 0) - (anchor.v.r or 0)) <= window then
				table.insert(group, e)
				if #group == need then return group end
			end
		end
		if need == 1 then return group end
	end
	return nil
end

-- Teams A / B. Ranked: snake draft by rating (best to A, next two to B, ...) so both sides are even.
local function splitTeams(group, ranked: boolean)
	local list = table.clone(group)
	if ranked then table.sort(list, function(a, b) return (a.v.r or 0) > (b.v.r or 0) end) end
	local order = ranked and { "A", "B", "B", "A" } or { "A", "B" }
	local teams = { A = {}, B = {} }
	for i, e in list do
		table.insert(teams[order[(i - 1) % #order + 1]], e.v.u)
	end
	return teams
end

local function claim(map, e, matchId: string): boolean
	local got = false
	pcall(function()
		map:UpdateAsync(e.key, function(old, sortKey)
			if type(old) ~= "table" or old.c or old.x then
				got = false
				return nil
			end
			got = true
			old.c = matchId
			return old, sortKey
		end, ENTRY_TTL)
	end)
	return got
end

local function unclaim(map, e, matchId: string)
	pcall(function()
		map:UpdateAsync(e.key, function(old, sortKey)
			if type(old) == "table" and old.c == matchId then
				old.c = nil
				return old, sortKey
			end
			return nil
		end, ENTRY_TTL)
	end)
end

-- [PARTY] the next match out of the pool, keeping parties whole: entries (oldest first) packed into team A / B, need / 2
-- players each (entry.v.n players, entry.v.p their ids). Ranked: every pair inside each other's window (RankedCore.PairOk).
-- Returns the picked entries and the teams as user id lists (nil teams = all solo: splitTeams balances them as before).
local function partyPick(pool, need: number, q, now: number)
	local function size(e) return math.max(1, math.floor(tonumber(e.v.n) or 1)) end
	local function ids(e) return type(e.v.p) == "table" and e.v.p or { e.v.u } end
	local function tierOf(e) return tonumber(e.v.k) or RankedCore.TierOf(e.v.r or 0) end
	if need == 1 then
		for _, e in pool do if size(e) == 1 then return { e }, nil end end
		return nil
	end
	local cap = need // 2
	for i, anchor in pool do
		if size(anchor) <= cap then
			local group, fill, teamOf = { anchor }, { A = size(anchor), B = 0 }, { [anchor] = "A" }
			for j, e in pool do
				if j ~= i then
					local s = size(e)
					local side = (fill.A + s <= cap and "A") or (fill.B + s <= cap and "B") or nil
					if side and q.Ranked then
						for _, g in group do
							if not RankedCore.PairOk(tierOf(g), now - (g.v.t or now), tierOf(e), now - (e.v.t or now), q.Mode) then side = nil break end
						end
					end
					if side then
						table.insert(group, e)
						teamOf[e] = side
						fill[side] += s
						if fill.A == cap and fill.B == cap then
							local allSolo = true
							for _, g in group do if size(g) > 1 then allSolo = false end end
							if allSolo then return group, nil end
							local teams = { A = {}, B = {} }
							for _, g in group do for _, u in ids(g) do table.insert(teams[teamOf[g]], u) end end
							return group, teams
						end
					end
				end
			end
		end
	end
	return nil
end

local function startMatch(q, group, matchId: string, packed): boolean -- [PARTY] packed teams
	local code = "STUDIO"
	local specId = nil -- [SECURE] the reserved server's PrivateServerId
	-- [SPLIT] ranked queues play in the Ranked place, casual ones in the Matchmaking place (0 = the old combined place);
	-- the id goes into the result, so the delivering server (any lobby server) teleports to the place the code belongs to
	local placeId = Config.PlaceIdFor(q.Ranked and "Ranked" or "Matchmaking")
	if not IS_STUDIO then
		local ok, res, sid = pcall(TeleportService.ReserveServer, TeleportService, placeId) -- [SECURE] sid
		if not ok then
			warn("[Matchmaking] ReserveServer failed: " .. tostring(res))
			return false
		end
		code = res
		specId = sid -- [SECURE]
	end
	-- [SPLIT] place = the reserved place id
	local result = { m = matchId, code = code, q = q.Id, mode = q.Mode, ranked = q.Ranked, teams = packed or splitTeams(group, q.Ranked), place = placeId } -- [PARTY] packed
	-- [SECURE] the match itself is written server-side (MatchSpec): TeleportData can be faked by the client.
	-- A ranked match whose spec can't be written isn't started (the players are unclaimed and matched again).
	if not IS_STUDIO then
		local MatchSpec = require(ServerScriptService.Shared.MatchSpec)
		local wrote = MatchSpec.Write(specId, { Mode = q.Mode, Ranked = q.Ranked == true, Queue = q.Id, MatchId = matchId, Teams = result.teams, Online = true, From = game.PlaceId })
		if not wrote and q.Ranked then return false end
	end
	-- [PARTY] every member of every picked entry gets the result
	for _, e in group do
		for _, uid in (type(e.v.p) == "table" and e.v.p or { e.v.u }) do
			pcall(function() results:SetAsync(tostring(uid), result, RESULT_TTL) end)
		end
	end
	local map = queueMap(q.Id)
	for _, e in group do
		pcall(function() map:RemoveAsync(e.key) end)
	end
	return true
end

local function publishCount(queueId: string, n: number)
	if os.clock() - (countsWritten[queueId] or 0) < COUNTS_EVERY - 0.5 then return end
	countsWritten[queueId] = os.clock()
	pcall(function()
		stats:UpdateAsync("counts", function(old)
			old = type(old) == "table" and old or {}
			old[queueId] = { n = n, t = os.time() }
			return old
		end, 60)
	end)
end

local function runQueue(q)
	if running[q.Id] then return end
	running[q.Id] = true
	local okRun, err = pcall(function()
		if not tryLock(q.Id) then return end
		local map = queueMap(q.Id)
		local ok, items = pcall(function() return map:GetRangeAsync(Enum.SortDirection.Ascending, 200) end)
		if not ok or type(items) ~= "table" then return end
		local pool = {}
		for _, it in items do
			local v = it.value
			if type(v) == "table" and v.u and not v.c and not v.x then
				table.insert(pool, { key = it.key, v = v })
			end
		end
		publishCount(q.Id, #pool)
		local now = workspace:GetServerTimeNow()
		local need = q.TeamSize * 2
		-- Studio, alone: once you've waited a moment you get a match of just you, so the flow can be tested
		if IS_STUDIO and Config.StudioSoloStart and #Players:GetPlayers() == 1 and #pool >= 1 and now - pool[1].v.t > 3 then
			need = 1
		end
		for _ = 1, 20 do
			-- [RANKED] the queue's mode for the window
			local group, packed = partyPick(pool, need, q, now) -- [PARTY] parties stay whole
			if not group then break end
			local matchId = HttpService:GenerateGUID(false)
			local claimed = {}
			for _, e in group do
				if claim(map, e, matchId) then table.insert(claimed, e) else break end
			end
			-- everyone picked leaves this pass either way (the ones let go are matched next pass)
			for _, e in group do
				local i = table.find(pool, e)
				if i then table.remove(pool, i) end
			end
			if #claimed == #group then -- [PARTY] entries, not players
				if not startMatch(q, claimed, matchId, packed) then
					for _, e in claimed do unclaim(map, e, matchId) end
					break
				end
			else
				for _, e in claimed do unclaim(map, e, matchId) end
			end
		end
	end)
	if not okRun then warn("[Matchmaking] " .. q.Id .. ": " .. tostring(err)) end
	running[q.Id] = nil
end

-------------------------------------------------------------------------------
-- This server's searching players: keep them queued, and send them off when matched
-------------------------------------------------------------------------------
local function deliver(player: Player, s, res)
	s.status = "Found"
	setState(player, s.queue, "Found")
	local name = string.upper(res.mode) .. (res.ranked and " RANKED" or "")
	Remotes.Notify(player, `{name} match found!`, "good")
	if IS_STUDIO then
		task.wait(2.5)
		if player.Parent and searching[player] == s then
			Remotes.Notify(player, "Teleports only work in a published game, so you stay here in Studio.", "info")
			stop(player)
		end
		return
	end
	task.wait(1.2) -- a beat to read "match found"
	if not player.Parent or searching[player] ~= s then return end
	s.status = "Teleporting"
	setState(player, s.queue, "Teleporting")
	-- [PARTY] the whole party goes in one teleport
	local partyGroup, partyLoadouts = {}, {}
	for _, m in PartyService.Members(player) do
		if m.Parent then table.insert(partyGroup, m); partyLoadouts[tostring(m.UserId)] = PlayerStore.Loadout(m) end
	end
	local options = Instance.new("TeleportOptions")
	options.ReservedServerAccessCode = res.code
	options:SetTeleportData({
		Mode = res.mode,
		Ranked = res.ranked,
		Queue = res.q,
		MatchId = res.m,
		Teams = res.teams,
		Loadouts = partyLoadouts, -- [PARTY] every member's loadout
		From = game.PlaceId,
		Online = true,
	})
	-- [DATA] save + release the profile first so the match server loads it at once; restore if the call fails
	local DataManager = require(game:GetService("ServerScriptService").Data.DataManager)
	for _, m in partyGroup do DataManager.ReleaseForTeleport(m) end -- [PARTY]
	-- [SPLIT] the place the match server was reserved on (a result written by a lobby server without [SPLIT] has none: the old place)
	local placeId = tonumber(res.place) or Config.MatchPlaceId
	local ok, err = pcall(TeleportService.TeleportAsync, TeleportService, placeId, partyGroup, options) -- [PARTY]
	if not ok then
		for _, m in partyGroup do task.spawn(DataManager.RestoreAfterTeleportFail, m, tostring(err)) end -- [PARTY]
		warn("[Matchmaking] TeleportAsync failed: " .. tostring(err))
		for _, pm in partyGroup do pm:SetAttribute("MM_FailReason", "Couldn't join the match server") end -- [MMFAIL]
		Remotes.Notify(player, "Couldn't join the match server. Try again.", "bad")
		stop(player)
	end
	-- [PLAYQUEUE] (systems grader) a teleport that never completes must not leave MM_Status stuck on Teleporting
	task.delay(30, function()
		if player.Parent and searching[player] == s and s.status == "Teleporting" then
			player:SetAttribute("MM_FailReason", "The match server didn't answer") -- [MMFAIL]
			Remotes.Notify(player, "The match server didn't answer. Try again.", "bad")
			stop(player)
		end
	end)
end

local function serviceSearchers()
	for player, s in searching do
		if s.status ~= "Searching" then continue end
		-- matched?
		local ok, res = pcall(function() return results:GetAsync(s.key) end)
		if ok and type(res) == "table" and res.q == s.queue then
			pcall(function() results:RemoveAsync(s.key) end)
			task.spawn(deliver, player, s, res)
			continue
		end
		-- still waiting: keep the entry alive (and put it back if it ever expired)
		if os.clock() - s.refreshed > REFRESH_EVERY then
			s.refreshed = os.clock()
			pcall(function()
				queueMap(s.queue):UpdateAsync(s.key, function(old, sortKey)
					if old == nil then
						-- [RANKED] k = tier
						return { u = player.UserId, j = game.JobId, r = s.rating, k = s.tier, t = s.since, n = s.n, p = s.p }, s.since -- [PARTY] n, p
					end
					if type(old) ~= "table" or old.x or old.c then return nil end
					return old, sortKey
				end, ENTRY_TTL)
			end)
		end
	end
end

local function readCounts()
	local ok, c = pcall(function() return stats:GetAsync("counts") end)
	local now = os.time()
	local out = {}
	for _, q in Config.Queues do
		local e = ok and type(c) == "table" and c[q.Id]
		out[q.Id] = (type(e) == "table" and now - (e.t or 0) < 15) and (e.n or 0) or 0
	end
	-- people searching from this server always count (the lease may be held elsewhere mid-pass)
	local here = {}
	for _, s in searching do
		if s.status == "Searching" then here[s.queue] = (here[s.queue] or 0) + 1 end
	end
	for id, n in here do out[id] = math.max(out[id] or 0, n) end
	ReplicatedStorage:SetAttribute("MM_Counts", HttpService:JSONEncode(out))
end

local function watch(player: Player)
	if IS_MATCH_PLACE then return end -- [PLAYQUEUE] no lobby pads here
	-- stepping onto a lobby pad takes you out of the online queue
	player:GetAttributeChangedSignal("QueueMode"):Connect(function()
		local s = searching[player]
		if player:GetAttribute("QueueMode") and s and s.status == "Searching" then
			if leaveQueue(s) then
				stop(player)
				Remotes.Notify(player, "Left the online queue: you're on a lobby pad", "info")
			end
		end
	end)
end

function MatchmakingManager.Start()
	-- [POSTMATCH] Play Again from a match place: TeleportData AutoQueue = <queue id> queues the player on arrival
	local partyClaims = {} -- [PSEUDOLOBBY] [leaderId] = the leader's own TeleportData.Party (members check against it)
	local function autoQueue(player: Player)
		if IS_MATCH_PLACE then return end -- [PLAYQUEUE] never queue from arrival TeleportData in a match place
		local ok, td = pcall(function() return player:GetJoinData().TeleportData end)
		local qid = ok and type(td) == "table" and td.AutoQueue
		if type(qid) ~= "string" or not Config.QueueById(qid) then return end
		-- [PSEUDOLOBBY] a party that pressed Play Again together re-forms here, then its leader queues for everyone
		local pty = type(td.Party) == "table" and type(td.Party.Members) == "table" and td.Party or nil
		local leaderId = pty and tonumber(pty.Leader)
		if leaderId == player.UserId then partyClaims[player.UserId] = pty end
		task.spawn(function()
			PlayerStore.Wait(player)
			if leaderId and leaderId ~= player.UserId then
				local t0 = os.clock()
				local leader = game:GetService("Players"):GetPlayerByUserId(leaderId)
				while not (leader and partyClaims[leaderId]) and os.clock() - t0 < 20 and player.Parent do
					task.wait(0.5); leader = game:GetService("Players"):GetPlayerByUserId(leaderId)
				end
				local claim = partyClaims[leaderId]
				if leader and claim and table.find(claim.Members, player.UserId) and player.Parent then
					local PS = require(game:GetService("ServerScriptService").Shared.PartyService)
					pcall(PS.Join, leader, player)
					return -- the leader queues the party
				end
				-- no matching leader claim: queue alone like a solo Play Again
			elseif leaderId then
				local t0 = os.clock()
				local function allIn()
					for _, id in pty.Members do
						local p = game:GetService("Players"):GetPlayerByUserId(tonumber(id) or 0)
						if p ~= player and (not p or p:GetAttribute("PartyLeader") ~= player.UserId) then return false end
					end
					return true
				end
				while os.clock() - t0 < 25 and player.Parent and not allIn() do task.wait(0.5) end
				partyClaims[player.UserId] = nil
			end
			task.wait(3)
			if player.Parent and not searching[player] then
				local res = findMatch(player, qid)
				if type(res) == "table" and res.msg then Remotes.Notify(player, res.msg, res.ok and "info" or "bad") end
			end
		end)
	end
	Players.PlayerAdded:Connect(autoQueue)
	for _, p in Players:GetPlayers() do autoQueue(p) end
	-- [PARTY] a roster change cancels the party's online search; a player who left a searching party loses the mirrored state
	PartyService.Changed.Event:Connect(function()
		for player, s in searching do
			if s.status == "Searching" and s.p then
				local now = {}
				for _, m in PartyService.Members(player) do table.insert(now, m.UserId) end
				if table.concat(now, ",") ~= table.concat(s.p, ",") then
					if leaveQueue(s) then
						stop(player)
						Remotes.Notify(player, "Your party changed: search cancelled", "info")
					end
				end
			end
		end
		for _, p in Players:GetPlayers() do
			if p:GetAttribute("MM_Queue") and not searching[p] then
				local party = PartyService.Of(p)
				if not (party and searching[party.leader]) then setState(p, nil, nil) end
			end
		end
	end)
	for _, p in Players:GetPlayers() do watch(p) end
	Players.PlayerAdded:Connect(watch)
	Players.PlayerRemoving:Connect(function(player)
		local s = searching[player]
		searching[player] = nil
		if s and s.status == "Searching" then task.spawn(leaveQueue, s) end
	end)
	TeleportService.TeleportInitFailed:Connect(function(player, _, message)
		local s = searching[player]
		if s and s.status == "Teleporting" then
			player:SetAttribute("MM_FailReason", "Teleport failed: " .. tostring(message)) -- [MMFAIL]
			Remotes.Notify(player, "Teleport failed: " .. tostring(message), "bad")
			stop(player)
		end
	end)
	ReplicatedStorage:SetAttribute("MM_Counts", "{}")
	-- [MM] offline-safe: no matchmaker loop without MemoryStore
	if OFFLINE then print("[Matchmaking] offline: MemoryStore unavailable (unpublished place)"); return end

	task.spawn(function()
		local lastCounts = 0
		while true do
			task.wait(TICK)
			serviceSearchers()
			-- run the matchmaker for every queue someone in this server is waiting in
			local active = {}
			for _, s in searching do
				if s.status == "Searching" then active[s.queue] = true end
			end
			for _, q in Config.Queues do
				if active[q.Id] then task.spawn(runQueue, q) end
			end
			if os.clock() - lastCounts >= COUNTS_EVERY then
				lastCounts = os.clock()
				task.spawn(readCounts)
			end
		end
	end)
	print("[Matchmaking] online queues ready" .. (IS_STUDIO and " (Studio namespace)" or ""))
end

return MatchmakingManager
]=====]
local mm = M:FindFirstChild("MatchmakingManager")
if UNDO then
	if mm and mm:GetAttribute("PlayQueue") then mm:Destroy(); table.insert(out, "module -") else table.insert(out, "module =") end
else
	assert(loadstring(MM_SRC), "MatchmakingManager source would not parse")
	if not mm then
		mm = Instance.new("ModuleScript")
		mm.Name = "MatchmakingManager"
		mm:SetAttribute("PlayQueue", true)
		mm.Source = MM_SRC
		mm.Parent = M
		table.insert(out, "module +")
	elseif mm.Source ~= MM_SRC then
		assert(mm:GetAttribute("PlayQueue"), "a MatchmakingManager that PLAYQUEUE didn't install is already here")
		mm.Source = MM_SRC
		table.insert(out, "module ~")
	else
		table.insert(out, "module =")
	end
end

-- 2. RoundManager
local HELPERS = [==[
-- [PLAYQUEUE] (Edward 2026-10-25) Play Again queues you from THIS server with the lobby's online queue (MatchmakingManager is
-- installed in the match places): the Searching pill shows over the results and the after-match lobby, and a match found
-- teleports you straight into a new reserved match server with the players you were matched with (no hub hop). Pressing it
-- again while searching cancels. No online queue here (an offline place): the old hub AutoQueue hop (playAgain).
-- (round 2, systems grader) presses are rate limited; a search only starts once this match's rewards are written for you and
-- your party (PQ_Awarded: the queue's teleport releases the profile); Leave / To Hub / a rematch refuse while a match has
-- already claimed you (the cancel can fail), so nobody is stranded or teleported twice.
local pqRate = {} -- [Player] = { t0, n, last }
Players.PlayerRemoving:Connect(function(p) pqRate[p] = nil end)
local function pqRateOk(player: Player): boolean
	local now, r = os.clock(), pqRate[player]
	if not r or now - r.t0 > 60 then r = { t0 = now, n = 0, last = -1 }; pqRate[player] = r end
	if now - r.last < 0.75 or r.n >= 20 then return false end
	r.last = now; r.n += 1
	return true
end
local function pqApi()
	local okM, MM = pcall(function() return require(ServerScriptService.ServerScripts["[Server] Init"].GameManager.Managers.MatchmakingManager) end)
	local okR, R = pcall(function() return require(ServerScriptService.Lobby.LobbyRemotes) end)
	if okM and type(MM) == "table" and MM.FindMatch and okR and R and R.Handlers then return MM, R end
	return nil, (okR and R or nil)
end
local function pqNotify(player: Player, text: string, kind: string?)
	local _, R = pqApi()
	if R and R.Notify then R.Notify(player, text, kind or "info") end
end
-- true = not (or no longer) in the online queue; false = a match already claimed them (they're on their way)
local function mmCancel(player: Player): boolean
	local mmSt = player:GetAttribute("MM_Status")
	if mmSt == nil then return true end
	if mmSt ~= "Searching" then return false end
	local MM, R = pqApi()
	if not (MM and R.Handlers.CancelMatch) then return true end
	if MM.IsSearching and not MM.IsSearching(player) then return true end -- a party member mirroring the leader's search
	local ok, res = pcall(R.Handlers.CancelMatch, player)
	return ok and type(res) == "table" and res.ok == true
end
local function pqPartyOf(player: Player)
	local PS = partyService()
	local party = PS and PS.Of(player)
	return PS, party
end
local function pqAwarded(player: Player): boolean
	-- (round 3) stamped with the game number, so a slow award from the last game never counts for this one
	local gameNo = ReplicatedStorage:GetAttribute("SeriesGames") or 0
	if player:GetAttribute("PQ_Awarded") ~= gameNo then return false end
	local _, party = pqPartyOf(player)
	if party and party.leader == player then
		for _, m in party.members do if m.Parent and m:GetAttribute("PQ_Awarded") ~= gameNo then return false end end
	end
	return true
end
local function pqWindowOpen(): boolean
	local ms = ReplicatedStorage:GetAttribute("MatchState")
	-- (round 3) series.closed: the after-match flow is over (timeout / hub) even though MatchState still reads MatchEnd
	return series ~= nil and not series.closed and (series.inPost or ms == "Victory" or ms == "MatchEnd")
end
local function startSearch(player: Player, qid: string)
	local MM = pqApi()
	if not MM then playAgain(player, qid) return end
	-- a party member who isn't the leader goes alone (as the hub Play Again did); the leader queues the whole party
	local PS, party = pqPartyOf(player)
	if party and #party.members > 1 and party.leader ~= player then PS.Leave(player, "left") end
	local ok, res = pcall(MM.FindMatch, player, qid)
	if ok and type(res) == "table" and res.offline then playAgain(player, qid) return end
	if not ok then warn("[RoundManager] [PLAYQUEUE] FindMatch failed: " .. tostring(res)) playAgain(player, qid) return end
	if type(res) == "table" and not res.ok and res.msg then pqNotify(player, res.msg, "bad") end
end
local function queueAgain(player: Player, qid: string)
	if not pqRateOk(player) then return end
	if not pqWindowOpen() or (series.sentHome and series.sentHome[player]) then return end -- (round 3) only in the after-match window
	local MM, R = pqApi()
	if not MM then playAgain(player, qid) return end
	local mmSt = player:GetAttribute("MM_Status")
	if mmSt == "Searching" then
		if MM.IsSearching and not MM.IsSearching(player) then pqNotify(player, "Only the party leader can cancel the search", "info") return end
		local ok, res = pcall(R.Handlers.CancelMatch, player)
		if ok and type(res) == "table" and res.msg then pqNotify(player, res.msg, res.ok and "info" or "bad") end
		return
	elseif mmSt ~= nil then
		return -- Found / Teleporting: already on the way
	end
	if pqAwarded(player) then startSearch(player, qid) return end
	-- rewards still being written (the Victory beat): start the search the moment they are
	if player:GetAttribute("PQ_Waiting") then return end
	player:SetAttribute("PQ_Waiting", true)
	task.spawn(function()
		local t0 = os.clock()
		while player.Parent and not pqAwarded(player) and os.clock() - t0 < 20 do task.wait(0.2) end
		player:SetAttribute("PQ_Waiting", nil)
		if player.Parent and pqAwarded(player) and pqWindowOpen() and player:GetAttribute("MM_Status") == nil then startSearch(player, qid)
		elseif player.Parent and not pqAwarded(player) then pqNotify(player, "Your match results are still saving. Press Play Again in a moment.", "bad") end
	end)
end
]==]

local edits = {
	{ "local function postMatchFlow(player: Player, kind: string)\n",
		HELPERS .. "\nlocal function postMatchFlow(player: Player, kind: string)\n" },
	{ "\tif not (s and (s.inPost or (kind == \"Rematch\" and ended))) then return end\n",
		"\t-- [PLAYQUEUE] Play Again works while the results show too (the search pill rides over Victory / Defeat)\n"
		.. "\tif not (s and (s.inPost or ((kind == \"Rematch\" or kind == \"PlayAgain\") and ended))) then return end\n" },
	{ "\telseif kind == \"ToHub\" then\n\t\tplayer:SetAttribute(\"InPseudoLobby\", nil)\n",
		"\telseif kind == \"ToHub\" then\n"
		.. "\t\tif not mmCancel(player) then pqNotify(player, \"Match found! Hold on...\", \"info\") return end -- [PLAYQUEUE] leave the queue first\n"
		.. "\t\tplayer:SetAttribute(\"InPseudoLobby\", nil)\n" },
	{ "\t\tplayAgain(player, queueIdOf(s.first)) -- [PSEUDOLOBBY] parties go together\n",
		"\t\tqueueAgain(player, queueIdOf(s.first)) -- [PLAYQUEUE] queue from here (was playAgain: the hub hop)\n" },
	{ "\t\tif os.clock() - t0 > (C.PostMatchTime or 300) then\n\t\t\tbackToLobby(Players:GetPlayers())\n\t\t\tresult = \"timeout\"\n\t\t\tbreak\n\t\tend\n",
		"\t\tif os.clock() - t0 > (C.PostMatchTime or 300) then\n"
		.. "\t\t\t-- [PLAYQUEUE] players still in the online queue stay until they're matched (or cancel); everyone else goes to the hub\n"
		.. "\t\t\ts.sentHome = s.sentHome or {}\n"
		.. "\t\t\tlocal home, waiting = {}, 0\n"
		.. "\t\t\tfor _, p in Players:GetPlayers() do\n"
		.. "\t\t\t\tif p:GetAttribute(\"MM_Status\") ~= nil or p:GetAttribute(\"PQ_Waiting\") then waiting += 1\n"
		.. "\t\t\t\telseif not s.sentHome[p] then s.sentHome[p] = true; table.insert(home, p) end\n"
		.. "\t\t\tend\n"
		.. "\t\t\tif #home > 0 then backToLobby(home) end\n"
		.. "\t\t\tif waiting == 0 then\n"
		.. "\t\t\t\tresult = \"timeout\"\n"
		.. "\t\t\t\tbreak\n"
		.. "\t\t\tend\n"
		.. "\t\tend\n" },
	{ "\t\t\tif still then result = \"rematch\" break end\n",
		"\t\t\tif still then\n"
		.. "\t\t\t\t-- [PLAYQUEUE] a rematch takes everyone out of the online queue; if a match already claimed someone, no rematch\n"
		.. "\t\t\t\tlocal free = true\n"
		.. "\t\t\t\tfor _, p in Players:GetPlayers() do local ms = p:GetAttribute(\"MM_Status\") if ms ~= nil and ms ~= \"Searching\" then free = false end end\n"
		.. "\t\t\t\tif free then for _, p in Players:GetPlayers() do if not mmCancel(p) then free = false end end end\n"
		.. "\t\t\t\tif free then\n"
		.. "\t\t\t\t\tresult = \"rematch\"\n"
		.. "\t\t\t\t\tbreak\n"
		.. "\t\t\t\tend\n"
		.. "\t\t\tend\n" },
	{ "\tif kind == \"Leave\" then\n\t\tlocal phase = ReplicatedStorage:GetAttribute(\"MatchState\")\n",
		"\tif kind == \"Leave\" then\n"
		.. "\t\tif not mmCancel(player) then pqNotify(player, \"Match found! Hold on...\", \"info\") return end -- [PLAYQUEUE] leave the queue first\n"
		.. "\t\tlocal phase = ReplicatedStorage:GetAttribute(\"MatchState\")\n" },
	{ "\t\t\t\tif not m.left then task.spawn(award, match, m, side, winner, forfeit, ratings) end\n",
		"\t\t\t\tif not m.left then\n"
		.. "\t\t\t\t\t-- [PLAYQUEUE] PQ_Awarded once this player's rewards are written (Play Again's teleport releases the profile)\n"
		.. "\t\t\t\t\ttask.spawn(function()\n"
		.. "\t\t\t\t\t\tlocal okA, errA = pcall(award, match, m, side, winner, forfeit, ratings)\n"
		.. "\t\t\t\t\t\tif not okA then warn(\"[RoundManager] award failed: \" .. tostring(errA)) end\n"
		.. "\t\t\t\t\t\tif m.player and m.player.Parent then m.player:SetAttribute(\"PQ_Awarded\", ReplicatedStorage:GetAttribute(\"SeriesGames\") or 0) end\n"
		.. "\t\t\t\t\tend)\n"
		.. "\t\t\t\tend\n" },
	{ "\t\tfor _, p in Players:GetPlayers() do p:SetAttribute(\"RematchVote\", nil) end\n\t\tseriesUpdate()\n",
		"\t\tfor _, p in Players:GetPlayers() do p:SetAttribute(\"RematchVote\", nil); p:SetAttribute(\"PQ_Awarded\", nil) end -- [PLAYQUEUE] a new game: rewards not written yet\n\t\tseriesUpdate()\n" },
	{ "\t\tlocal r = postMatch()\n\t\tif r ~= \"rematch\" then return end\n",
		"\t\tlocal r = postMatch()\n\t\tif r ~= \"rematch\" then series.closed = true return end -- [PLAYQUEUE] the after-match window is over\n" },
}
local s = RM.Source:gsub("\r\n", "\n")
for i, e in edits do
	local o, n = e[1], e[2]
	if UNDO then o, n = n, o end
	local done
	if UNDO then done = not s:find(o, 1, true) else done = s:find(n, 1, true) ~= nil end
	if done then
		table.insert(out, i .. "=")
	else
		local a, b = s:find(o, 1, true)
		assert(a, "RoundManager edit " .. i .. " anchor not found")
		assert(not s:find(o, b + 1, true), "RoundManager edit " .. i .. " anchor not unique")
		s = s:sub(1, a - 1) .. n .. s:sub(b + 1)
		table.insert(out, i .. "+")
	end
end
local f, err = loadstring(s)
assert(f, "RoundManager would not parse: " .. tostring(err))
if RM.Source ~= s then RM.Source = s end
return "PLAYQUEUE " .. table.concat(out, " ")
